statisticsRows(){let m={};for(let t of this.cfg.teachers){let lessons=Object.values(t.lessons||{}).reduce((n,d)=>n+Object.keys(d||{}).length,0);m[t.name]={name:t.name,group:t.group,lessons,d13:0,school:0,total:0,minutes:0,minutesPerLesson:0,long:0,wait:0,Pn:0,Wt:0,'Śr':0,Czw:0,Pi:0}}let mins={};for(let b of this.cfg.breaks)mins[b.abbr+'|'+b.label]=Number(b.minutes||0);for(let r of(this.statsAssignments13||[]))for(let a of(r.assignments||[])){if(!a.teacher||!m[a.teacher])continue;let x=m[a.teacher],mm=mins[r.abbr+'|'+r.label]||0;x.d13++;x.total++;x.minutes+=mm;if(mm>10)x.long++;if(a.wait)x.wait++;x[r.abbr]++}for(let d of(this.statsAssignmentsSchool||[])){if(!d.teacher||!m[d.teacher])continue;let x=m[d.teacher],mm=mins[d.abbr+'|'+d.slot]||0;x.school++;x.total++;x.minutes+=mm;if(mm>10)x.long++;if(d.wait)x.wait++;x[d.abbr]++}for(let x of Object.values(m))x.minutesPerLesson=x.lessons?Number((x.minutes/x.lessons).toFixed(1)):0;return Object.values(m).sort((a,b)=>teacherSortKey(a.name).localeCompare(teacherSortKey(b.name),'pl',{sensitivity:'base'}))},
filteredStatistics(){let q=this.statsSearch.toLowerCase(),f=this.statsColumnFilters||{};let rows=this.statisticsRows.filter(x=>(!q||x.name.toLowerCase().includes(q)||this.dn(x.name).toLowerCase().includes(q))&&(!this.statsGroupFilter||x.group===this.statsGroupFilter)&&(this.statFilterMatch(x.name,f.name)||this.statFilterMatch(this.dn(x.name),f.name))&&this.statFilterMatch(x.group,f.group)&&['lessons','d13','school','total','minutes','minutesPerLesson','long','wait','Pn','Wt','Śr','Czw','Pi'].every(k=>this.statFilterMatch(x[k],f[k])));let k=this.statsSortKey,dir=this.statsSortDir;return rows.sort((a,b)=>{if(k==='name')return teacherSortKey(a.name).localeCompare(teacherSortKey(b.name),'pl',{sensitivity:'base'})*dir;let av=a[k],bv=b[k];if(typeof av==='number'&&typeof bv==='number')return(av-bv)*dir;return String(av).localeCompare(String(bv),'pl',{numeric:true})*dir})},
statsMaxMinutes(){return Math.max(1,...this.statisticsRows.map(x=>Number(x.minutes||0)))},
