openDutyCellAction(e){let duties=e.duties||[],positions=(this.manualMissingPositions?.[e.abbr+'|'+e.slot]||[]);if(duties.length){let d=duties[0];this.manualDutyEdit={operation:'remove',actor:'teacher',teacher:e.teacher,position:d,positions:duties,postAction:'pause'}}else if(positions.length){this.manualDutyEdit={operation:'add',actor:'teacher',teacher:e.teacher,position:positions[0],positions,postAction:'pause'}}else{this.manualDutyEdit={operation:'prefer',actor:'teacher',teacher:e.teacher,position:{abbr:e.abbr,slot:e.slot,scope:'1-3',location:''},positions:[],postAction:'pause'}}},
