teacherDutyMap(name,a13,school){let m={};for(let r of(a13||[]))for(let a of(r.assignments||[]))if(a.teacher===name){let k=r.abbr+'|'+r.label;(m[k]||(m[k]=[])).push('1–3 • '+(a.station||''))}for(let x of(school||[]))if(x.teacher===name){let k=x.abbr+'|'+x.slot;(m[k]||(m[k]=[])).push('szkoła • '+(x.location||''))}return m},
openTeacherComparison(sug,name){let t=this.cfg.teachers.find(x=>x.name===name);if(!t)return;let before=this.teacherDutyMap(name,this.rows13,this.schoolCurrent),after=this.teacherDutyMap(name,sug.result_13||[],sug.result_school||[]);let hasBefore=Object.values(before).some(x=>x?.length),rows=[];for(let d of this.dayCodeOptions){for(let r of(this.cfg.timeline?.[d.label]||[])){let key=d.code+'|'+(r.kind==='LEKCJA'?String(r.key):String(r.label));let lesson=r.kind==='LEKCJA'?this.lessonText(t,d.code,r.key):'';let b=r.kind==='PRZERWA'?(before[key]||[]).join(' / '):'';let a=r.kind==='PRZERWA'?(after[key]||[]).join(' / '):'';if(!lesson&&!b&&!a)continue;rows.push({day:d.label,time:r.time,label:r.kind==='LEKCJA'?'Lekcja '+r.label:'Przerwa '+r.label,lesson,before:b,after:a,changed:b!==a})}}this.teacherCompare={rawName:name,displayName:this.dn(name),hasBefore,rows}},
isFixedConstraint(c){return['no_lesson_overlap','one_place_per_slot','cross_scope_conflict','manual_blocks'].includes(c?.key)},

