sortMark(k){return this.statsSortKey===k?(this.statsSortDir===1?'▲':'▼'):''},
statFilterMatch(value,filter){let f=String(filter??'').trim().toLowerCase();if(!f)return true;let s=String(value??'').toLowerCase(),n=Number(value);let range=f.match(/^(-?\d+(?:[.,]\d+)?)\s*-\s*(-?\d+(?:[.,]\d+)?)$/);if(range&&!Number.isNaN(n)){let a=Number(range[1].replace(',','.')),b=Number(range[2].replace(',','.'));return n>=Math.min(a,b)&&n<=Math.max(a,b)}let m=f.match(/^(>=|<=|>|<|=)?\s*(-?\d+(?:[.,]\d+)?)$/);if(m&&!Number.isNaN(n)){let x=Number(m[2].replace(',','.')),op=m[1]||'=';return op==='>='?n>=x:op==='<='?n<=x:op==='>'?n>x:op==='<'?n<x:n===x}return s.includes(f)},
