partialTokenLabel(t){
 let p=String(t||'').split(':');
 let labels={max_day_13:'limit dyżurów dziennie w 1–3',max_day_school:'limit dyżurów dziennie w całej szkole',max_week:'limit dyżurów tygodniowo',max_long_day:'limit długich przerw dziennie',max_long_week:'limit długich przerw tygodniowo',max_consecutive_duties:'limit kolejnych dyżurów',before_first_short:'krótka przerwa przed pierwszą lekcją (bez 0/1)',after_last_short:'krótka przerwa po ostatniej lekcji',before_first_long:'dłuższa przerwa przed pierwszą lekcją',after_last_long:'dłuższa przerwa po ostatniej lekcji',balance_day:'równoważenie obciążenia w dniu',balance_week:'równoważenie obciążenia w tygodniu',lesson_load_fairness:'sprawiedliwy udział wg obciążenia dydaktycznego',prefer_home_group:'preferowanie własnej grupy',avoid_wait:'unikanie dodatkowego oczekiwania'};
 if(p[0]==='gval')return 'Zmień '+(labels[p[1]]||p[1])+' na '+p[2];
 if(p[0]==='m13'){let [ab,slot,val]=p.slice(1).join(':').split('|');return 'Obsada 1–3 '+ab+' '+slot+': ustaw '+val}
 if(p[0]==='ms'){let z=p.slice(1).join(':').split('|'),val=z.pop(),ab=z.shift(),slot=z.shift(),loc=z.join('|');return 'Obsada szkoły '+ab+' '+slot+' • '+loc+': ustaw '+val}
 if(p[0]==='gsoft')return 'Zmień „'+(labels[p[1]]||p[1])+'” z bezwzględnego wymogu na zalecenie';
 if(p[0]==='trelax'){let z=p.slice(1).join(':').split('|');return 'Indywidualne ustępstwo '+this.dn(z[0])+': '+(labels[z[1]]||z[1])}
 if(p[0]==='add13')return 'Dodaj '+this.dn(p.slice(1).join(':'))+' do puli 1–3';
 if(p[0]==='addschool')return 'Dodaj '+this.dn(p.slice(1).join(':'))+' do puli całej szkoły';
 if(p[0]==='move13')return 'Przenieś '+this.dn(p.slice(1).join(':'))+' z puli całej szkoły do puli 1–3';
 if(p[0]==='moveschool')return 'Przenieś '+this.dn(p.slice(1).join(':'))+' z puli 1–3 do puli całej szkoły';
 if(t==='add13group:school')return 'Dodaj nauczycieli ogólnych do puli 1–3';
 if(t==='add13group:wf')return 'Dodaj nauczycieli WF do puli 1–3';
 if(p[0]==='indval')return 'Zmień indywidualny limit nauczyciela na '+p[p.length-1];
 if(p[0]==='indsoft')return 'Zmień indywidualny bezwzględny wymóg na zalecenie';
 if(p[0]==='unblock')return 'Usuń ręczną blokadę kolidującą z dyżurem';
 if(p[0]==='unlock')return 'Odblokuj stały przydział kolidujący z dyżurem';
 return String(t||'').replaceAll('_',' ');
},
