partialSourceLabel(x){let src=x?.source==='remote'?'zdalny worker':'NODE00';let ph=String(x?.phase||'');if(ph.startsWith('deep'))return src+' • dokładne sprawdzenie';if(ph.includes('ceiling'))return src+' • test możliwości';return src+' • szybka próba'},
