async copyTextSafe(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}}catch(e){}let ta=document.createElement('textarea');ta.value=text;ta.setAttribute('readonly','');ta.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(ta);ta.select();ta.setSelectionRange(0,ta.value.length);let ok=false;try{ok=document.execCommand('copy')}catch(e){}ta.remove();return ok},
async copyTeacherPortalFor(t){let ok=await this.copyTextSafe(this.teacherPortalUrl(t));this.teacherAdminMessage=ok?'Skopiowano link dla '+t.name:'Nie udało się skopiować linku — zaznacz go w polu powyżej.'},
