 if(scope==='school'){for(let day of this.days){let dc={'Poniedziałek':'Pn','Wtorek':'Wt','Środa':'Śr','Czwartek':'Czw','Piątek':'Pi'}[day];let rows=this.schoolLocations.map(loc=>[loc,...this.schoolSlots.map(sl=>this.schoolPlanDisplay.find(x=>x.abbr===dc&&String(x.location)===String(loc)&&x.slot===sl)?.teacher||'')]);box.appendChild(mk(day,['Miejsce',...this.schoolSlots],rows))}}
